// --- Text Formatting Helper (Enhanced with KaTeX) ---
// Handles Block Math ($$ ... $$), Inline Math ($ ... $), and Bold (** ... **)
const FormattedTextRenderer: React.FC<{ text: string }> = ({ text }) => {
    if (!text) return null;

    // 1. Split by Block Math $$...$$
    // Regex matches $$ content $$
    const parts = text.split(/(\$\$[\s\S]*?\$\$)/g);

    return (
        <div className="text-sm leading-relaxed space-y-2">
            {parts.map((part, i) => {
                if (part.startsWith('$$') && part.endsWith('$$')) {
                    // Render Block Math
                    const math = part.slice(2, -2).trim();
                    try {
                        const html = katex.renderToString(math, { 
                            displayMode: true, 
                            throwOnError: false 
                        });
                        return <div key={i} dangerouslySetInnerHTML={{ __html: html }} className="my-3 overflow-x-auto text-center" />;
                    } catch (e) {
                        return <code key={i} className="block bg-gray-100 dark:bg-gray-800 p-2 rounded">{part}</code>;
                    }
                } else {
                    // Render Inline content
                    return <span key={i}>{renderInlineContent(part)}</span>;
                }
            })}
        </div>
    );
};

const renderInlineContent = (text: string) => {
    // 2. Split by Inline Math $...$
    // Using simple regex for non-nested $...$
    const parts = text.split(/(\$[^\$]+\$)/g);

    return parts.map((part, i) => {
        if (part.startsWith('$)') && part.endsWith('$') && part.length > 2) {
             const math = part.slice(1, -1);
             try {
                const html = katex.renderToString(math, { 
                    displayMode: false, 
                    throwOnError: false 
                });
                return <span key={i} dangerouslySetInnerHTML={{ __html: html }} />;
             } catch (e) {
                 return <span key={i}>{part}</span>;
             }
        }
        // 3. Fallback to Basic Formatting (Bold)
        return <span key={i}>{renderBasicFormatting(part)}</span>;
    });
}

const renderBasicFormatting = (text: string) => {
    // Handle **Bold**
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, i) => {
        if (part.startsWith('**') && part.endsWith('**')) {
             return <strong key={i}>{part.slice(2, -2)}</strong>;
        }
        return <span key={i}>{part}</span>;
    });
}


// --- Audio Helper Functions ---
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

function createBlob(data: Float32Array): GenAiBlob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

