    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
    const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
    const mediaStreamRef = useRef<MediaStream | null>(null);
    const outputSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
    const nextStartTimeRef = useRef<number>(0);
    const currentTurnRef = useRef({ userInput: '', modelOutput: '' });

    // --- State for Self-Learning ---
    const [userPreferences, setUserPreferences] = useState<UserPreferences>({
        emotionCounts: {},
        avgUserMessageLength: 0,
        messageCount: 0,
        positiveHumorResponse: 0,
        facts: [],
        interests: [],
        tone: '',
    });

    // Memory Optimization: Use a buffer to batch updates instead of sending every message
    const memoryBufferRef = useRef<string>(""); 
    const lastMemoryUpdateRef = useRef<number>(0);

    // FIX: Ref to track latest messages state for use in stale closures (like voice callbacks)
    const messagesRef = useRef<NovaMessage[]>([]);

    const messagesEndRef = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const debounceTimerRef = useRef<number | null>(null);

    const generatePreferenceSummary = (prefs: UserPreferences): string => {
        if (prefs.messageCount < 3) return ''; // Wait for a few messages to build a profile
        let summary = '[Stats: ';
        const dominantEmotion = Object.keys(prefs.emotionCounts).reduce((a, b) => prefs.emotionCounts[a] > prefs.emotionCounts[b] ? a : b, '');
        if (dominantEmotion) summary += `Dominant emotion: ${dominantEmotion}. `;
        if (prefs.avgUserMessageLength < 15) summary += 'Writes concisely. ';
        else if (prefs.avgUserMessageLength > 50) summary += 'Writes detailed messages. ';
        if (prefs.positiveHumorResponse > 0) summary += 'Responds to humor. ';
        summary += ']';
        return summary;
    };

    // --- KLING API INTEGRATION ---
    const generateKlingToken = async () => {
        const secret = new TextEncoder().encode(KLING_SECRET_KEY);
        const alg = 'HS256';
        const jwt = await new SignJWT({})
            .setProtectedHeader({ alg, typ: 'JWT' })
            .setIssuer(KLING_ACCESS_KEY)
            .setExpirationTime('30m') // Token valid for 30 minutes
            .setNotBefore('0s')
            .sign(secret);
        return jwt;
    };

    const generateVideoWithKling = async (prompt: string): Promise<string | null> => {
        try {
            const token = await generateKlingToken();
            const baseUrl = "https://api.klingai.com/v1/videos/text2video";

            // 1. Submit Task
            const submitResponse = await fetch(baseUrl, {
                method: "POST",
                headers: {
                    "Authorization": `Bearer ${token}`,
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    model_name: "kling-v1",
                    prompt: prompt,
                    cfg_scale: 0.5 // Default creativity
                })
            });

            if (!submitResponse.ok) {
                const errData = await submitResponse.json();
                console.error("Kling API Submit Error:", errData);
                throw new Error(errData.message || "Failed to start video generation.");
            }

            const submitData = await submitResponse.json();
            const taskId = submitData.data?.task_id;
            if (!taskId) throw new Error("No task ID returned from Kling.");

            // 2. Poll for Completion
            let attempts = 0;
            const maxAttempts = 60; // 5 mins max (5s * 60)

            return new Promise((resolve, reject) => {
                const poll = async () => {
                    if (attempts >= maxAttempts) {
                        reject(new Error("Video generation timed out."));
                        return;
                    }

                    try {
                        const statusResponse = await fetch(`${baseUrl}/${taskId}`, {
                            method: "GET",
                            headers: { "Authorization": `Bearer ${token}` }
                        });

                        const statusData = await statusResponse.json();
                        const taskStatus = statusData.data?.task_status;

                        if (taskStatus === "succeed") {
                             // Success!
                             const videoUrl = statusData.data?.task_result?.videos?.[0]?.url;
                             if (videoUrl) {
                                 // Fetch to blob to upload to our storage
                                 const vidRes = await fetch(videoUrl);
                                 const blob = await vidRes.blob();
                                 const { url } = await uploadMedia(blob, userProfile!.uid, 'audio'); // 'audio' purpose stores in video-friendly path in logic
                                 resolve(url);
                             } else {
                                 reject(new Error("Task succeeded but no video URL found."));
                             }
                        } else if (taskStatus === "failed") {
                            reject(new Error(statusData.data?.task_status_msg || "Video generation task failed."));
                        } else {
                            // running, submitted, etc.
                            attempts++;
                            setTimeout(poll, 5000); // Poll every 5s
                        }
                    } catch (e) {
                        console.error("Polling error:", e);
                        reject(e);
                    }
                };
                poll();
            });

