            const errStr = e.message || String(e) || JSON.stringify(e);
            if (errStr.includes("429") || errStr.includes("RESOURCE_EXHAUSTED") || errStr.includes("quota")) {
                 console.warn("Memory update skipped (Rate Limit Exceeded) - data discarded to prevent backlog.");
                 return;
            }
            console.warn("Memory update failed", e);
        }
