    const handleDownloadImage = (msgId: string, imageUrl: string, filename: string) => {
        setDownloadingFile(msgId);

        // If it's a data URI
        if (imageUrl.startsWith('data:')) {
             const mimeType = imageUrl.match(/data:([^;]+);/)?.[1] || 'image/jpeg';
             const base64 = imageUrl.split(',')[1];
             const byteCharacters = atob(base64);
             const byteNumbers = new Array(byteCharacters.length);
             for (let i = 0; i < byteCharacters.length; i++) byteNumbers[i] = byteCharacters.charCodeAt(i);
             const byteArray = new Uint8Array(byteNumbers);
             const blob = new Blob([byteArray], { type: mimeType });
             const url = URL.createObjectURL(blob);
             downloadFile(url, filename);
             setDownloadingFile(null);
             return;
        }

        // If it's a Cloud URL
        fetch(imageUrl)
            .then(response => response.blob())
            .then(blob => {
                const url = URL.createObjectURL(blob);
                downloadFile(url, filename);
            })
            .catch(err => {
                console.error("Image download failed", err);
                window.open(imageUrl, '_blank');
            })
            .finally(() => {
                setDownloadingFile(null);
            });
    };

    const handleDownloadPdf = (msgId: string, text: string, filename: string) => {
        setDownloadingFile(msgId);

        const doc = new jsPDF({
            orientation: 'portrait',
            unit: 'pt',
            format: 'a4'
        });

        const pageWidth = doc.internal.pageSize.getWidth();
        const pageHeight = doc.internal.pageSize.getHeight();
        const margin = 40;
        const maxLineWidth = pageWidth - (margin * 2);

        let pageNumber = 1;
        const addPageWithHeader = () => {
             doc.addPage();
             pageNumber++;
             return margin + 20;
        }

        let y = margin;

        // --- Header (First Page) ---
        doc.setFillColor(14, 165, 233);
        doc.rect(0, 0, pageWidth, 5, 'F');

        doc.setFont("helvetica", "bold");
        doc.setFontSize(22);
        doc.setTextColor(51, 65, 85);
        doc.text("Nova Intelligence", margin, y + 30);
        y += 45;

        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(100, 116, 139);
        const dateStr = new Date().toLocaleDateString();
        doc.text(`Generated by CollabSea • ${dateStr}`, margin, y);
        y += 20;

        doc.setDrawColor(226, 232, 240);
        doc.line(margin, y, pageWidth - margin, y);
        y += 35;

        doc.setTextColor(30, 41, 59);

        let cleanText = text.replace(/^(Sure|Here|I have|Certainly).*?(\n\n|\n)/i, '');
        cleanText = cleanText.replace(/\*\*(.*?)\*\*/g, '$1').replace(/\*(.*?)\*/g, '$1');

        const lines = cleanText.split('\n');

        lines.forEach((line) => {
            const trimmed = line.trim();
            if (!trimmed) {
                y += 10;
                return;
            }

            if (trimmed === '---') {
                y = addPageWithHeader();
                return;
            }

            if (trimmed.startsWith('# ')) {
                doc.setFont("helvetica", "bold");
                doc.setFontSize(18);
                const title = trimmed.replace('# ', '');
                const titleLines = doc.splitTextToSize(title, maxLineWidth);
                doc.text(titleLines, margin, y);
                y += (titleLines.length * 22) + 10;
                return;
            }

            if (trimmed.startsWith('## ')) {
                doc.setFont("helvetica", "bold");
                doc.setFontSize(14);
                const subtitle = trimmed.replace('## ', '');
                const subLines = doc.splitTextToSize(subtitle, maxLineWidth);
                doc.text(subLines, margin, y);
                y += (subLines.length * 18) + 8;
                return;
            }

            if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
                doc.setFont("helvetica", "normal");
                doc.setFontSize(11);
                const bulletText = trimmed.substring(2);
                const bulletLines = doc.splitTextToSize(bulletText, maxLineWidth - 15);

                doc.text('•', margin, y);
                doc.text(bulletLines, margin + 15, y);
                y += (bulletLines.length * 14) + 5;

                 if (y > pageHeight - margin) {
                    y = addPageWithHeader();
                }
                return;
            }

            doc.setFont("helvetica", "normal");
            doc.setFontSize(11);
            const textLines = doc.splitTextToSize(trimmed, maxLineWidth);

            if (y + (textLines.length * 14) > pageHeight - margin) {
                y = addPageWithHeader();
            }

            doc.text(textLines, margin, y);
            y += (textLines.length * 14) + 10;
        });

        const pageCount = doc.internal.pages.length - 1;
        for (let i = 1; i <= pageCount; i++) {
            doc.setPage(i);
            doc.setFontSize(9);
            doc.setTextColor(148, 163, 184);
            doc.text(`Page ${i} of ${pageCount}`, pageWidth - margin, pageHeight - 20, { align: 'right' });
        }

        doc.save(filename);
        setDownloadingFile(null);
    };

    const handleDownloadZip = async (text: string) => {
        setGenerationMessage("Compressing project files...");
        try {
            const zip = new JSZip();
            const fileRegex = /@@FILE:\s*([^\s@]+)@@[\s\S]*?```[\w-]*\s*([\s\S]*?)```/g;
            let match;
            let count = 0;

            while ((match = fileRegex.exec(text)) !== null) {
                count++;
                let filePath = match[1].trim();
                filePath = filePath.replace(/['"`]/g, ''); 
                let fileContent = match[2];
                fileContent = fileContent.replace(/^\n+/, '').replace(/\n+$/, '');
                zip.file(filePath, fileContent);
            }

            if (count === 0) {
                alert("Could not parse project files. The output format might have been incorrect. Please try generating again.");
                setGenerationMessage(null);
                return;
            }

            const content = await zip.generateAsync({ type: "blob" });
            const url = URL.createObjectURL(content);
            const a = document.createElement("a");
            a.href = url;
            a.download = "nova-app-project.zip";
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        } catch (e) {
            console.error("Zip error", e);
            alert("Failed to create zip file.");
        } finally {
            setGenerationMessage(null);
        }
    };

