        const currentSkill = activeSkill;
        setInput('');
        setUploadedFile(null);

        const emotion = await analyzeEmotionWithHuggingFace(text);

        setUserPreferences(prev => {
            const newEmotionCounts = { ...prev.emotionCounts };
            if (emotion) newEmotionCounts[emotion.label] = (newEmotionCounts[emotion.label] || 0) + 1;
            const newMessageCount = prev.messageCount + 1;
            const newTotalLength = (prev.avgUserMessageLength * prev.messageCount) + text.length;

            return {
                ...prev,
                emotionCounts: newEmotionCounts,
                messageCount: newMessageCount,
                avgUserMessageLength: newTotalLength / newMessageCount,
            };
        });

        const userMessage: Omit<NovaMessage, 'id'> = {
            role: 'user',
            text,
            timestamp: serverTimestamp() as Timestamp,
            ...(emotion && { emotion }),
            ...(currentFile?.type === 'image' && { uploadedImageUrl: currentFile.content }),
        };

        const historyRef = collection(db, 'users', userProfile.uid, 'nova_history');
        await addDoc(historyRef, userMessage);

        updateUserMemory(text);

        executeSkill(text, currentFile, currentSkill, emotion);
    };

    const stopVoiceSession = () => {
        if (sessionPromiseRef.current) {
            sessionPromiseRef.current.then(session => session.close()).catch(e => console.debug("Session close error", e));
        }
        scriptProcessorRef.current?.disconnect();
        mediaStreamSourceRef.current?.disconnect();
        mediaStreamRef.current?.getTracks().forEach(track => track.stop());

        if (inputAudioContextRef.current && inputAudioContextRef.current.state !== 'closed') {
            inputAudioContextRef.current.close().catch(e => console.debug("Input AC close error", e));
        }
        if (outputAudioContextRef.current && outputAudioContextRef.current.state !== 'closed') {
            outputAudioContextRef.current.close().catch(e => console.debug("Output AC close error", e));
        }

        outputSourcesRef.current.forEach(s => s.stop());

        sessionPromiseRef.current = null;
        setVoiceConnectionState('idle');
        setLiveTranscription({userInput: '', modelOutput: ''});
        currentTurnRef.current = {userInput: '', modelOutput: ''};
    };

    const startVoiceSession = async () => {
        if (!userProfile) return;
        setVoiceConnectionState('connecting');
        setApiError(null);

        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            mediaStreamRef.current = stream;

            const inputCtx = new AudioContext({ sampleRate: 16000 });
            const outputCtx = new AudioContext({ sampleRate: 24000 });

            await inputCtx.resume();
            await outputCtx.resume();

            inputAudioContextRef.current = inputCtx;
            outputAudioContextRef.current = outputCtx;

            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            const systemInstruction = getVoiceSystemInstruction();

            sessionPromiseRef.current = ai.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setVoiceConnectionState('connected');
                        if (!inputAudioContextRef.current) return;

                        mediaStreamSourceRef.current = inputAudioContextRef.current.createMediaStreamSource(stream);
                        scriptProcessorRef.current = inputAudioContextRef.current.createScriptProcessor(4096, 1, 1);
                        scriptProcessorRef.current.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            sessionPromiseRef.current?.then((s) => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };
                        mediaStreamSourceRef.current.connect(scriptProcessorRef.current);
                        scriptProcessorRef.current.connect(inputAudioContextRef.current.destination);
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        if (message.toolCall) {
                            for (const fc of message.toolCall.functionCalls) {
                                if (fc.name === 'switchSkill') {
                                    const { skill, prompt } = fc.args;
                                    if (skill && prompt) {
                                        sessionPromiseRef.current?.then((session) => {
                                            session.sendToolResponse({
                                                functionResponses: {
                                                    id : fc.id,
                                                    name: fc.name,
                                                    response: { result: `Action initiated. Task is running in background.` },
                                                }
                                            });
                                        });

                                        let targetSkill: ActiveSkill = 'chat';
                                        const lowerSkill = (skill as string).toLowerCase();
                                        if (lowerSkill.includes('image') || lowerSkill.includes('photo')) targetSkill = 'imageGen';
                                        else if (lowerSkill.includes('video') || lowerSkill.includes('movie')) targetSkill = 'videoGen';
                                        else if (lowerSkill.includes('doc') || lowerSkill.includes('pdf')) targetSkill = 'docGen';
                                        else if (lowerSkill.includes('app') || lowerSkill.includes('code')) targetSkill = 'appGen';
                                        else if (lowerSkill.includes('trend')) targetSkill = 'trends';
                                        else if (lowerSkill.includes('work')) targetSkill = 'workflow';
                                        else if (lowerSkill.includes('scam')) targetSkill = 'scamDetect';

                                        executeSkill(prompt, null, targetSkill);
                                    }
                                }
                            }
                        }

                        if (message.serverContent?.inputTranscription) currentTurnRef.current.userInput += message.serverContent.inputTranscription.text;
                        if (message.serverContent?.outputTranscription) currentTurnRef.current.modelOutput += message.serverContent.outputTranscription.text;
                        setLiveTranscription({ ...currentTurnRef.current });

                        if (message.serverContent?.turnComplete && userProfile) {
                            const fullInput = currentTurnRef.current.userInput;
                            const fullOutput = currentTurnRef.current.modelOutput;
                            currentTurnRef.current = { userInput: '', modelOutput: '' };

                            (async () => {
                                const historyRef = collection(db, 'users', userProfile.uid, 'nova_history');
                                if (fullInput.trim()) {
                                    const emotion = await analyzeEmotionWithHuggingFace(fullInput);

                                    setUserPreferences(prev => {
                                        const newEmotionCounts = { ...prev.emotionCounts };
                                        if (emotion) newEmotionCounts[emotion.label] = (newEmotionCounts[emotion.label] || 0) + 1;
                                        const newMessageCount = prev.messageCount + 1;
                                        const newTotalLength = (prev.avgUserMessageLength * prev.messageCount) + fullInput.length;
                                        return {
                                            ...prev,
                                            emotionCounts: newEmotionCounts,
                                            messageCount: newMessageCount,
                                            avgUserMessageLength: newTotalLength / newMessageCount,
                                        };
                                    });

                                    const userMessagePayload = {
                                        role: 'user' as const,
                                        text: fullInput,
                                        fromSkill: 'voice' as const,
                                        timestamp: serverTimestamp(),
                                        ...(emotion && { emotion }),
                                    };
                                    await addDoc(historyRef, userMessagePayload);
                                    updateUserMemory(fullInput);
                                }
                                if (fullOutput.trim()) {
                                    await addDoc(historyRef, { role: 'model', text: fullOutput, fromSkill: 'voice', timestamp: serverTimestamp() });
                                }
                            })();
                        }
                        const outputCtx = outputAudioContextRef.current;
                        if (!outputCtx) return;

                        const audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audio) {
                            nextStartTimeRef.current = Math.max(
                                nextStartTimeRef.current,
                                outputCtx.currentTime
                            );
                            const buffer = await decodeAudioData(decode(audio), outputCtx, 24000, 1);
                            const source = outputCtx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(outputCtx.destination);

                            source.addEventListener('ended', () => {
                                outputSourcesRef.current.delete(source);
                            });

                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += buffer.duration;
                            outputSourcesRef.current.add(source);
                        }

                        const interrupted = message.serverContent?.interrupted;
                        if (interrupted) {
                            for (const source of outputSourcesRef.current.values()) {
                                source.stop();
                                outputSourcesRef.current.delete(source);
                            }
                            nextStartTimeRef.current = 0;
                        }
                    },
                    onerror: (e: ErrorEvent) => {
                        console.error("Voice WebSocket Error:", e);
                        setVoiceConnectionState('error');
                        setApiError("Voice connection failed. Retrying...");
                    },
                    onclose: (e) => {
                        console.log("Voice Session Closed", e);
                        if (voiceConnectionState === 'connected') {
                             stopVoiceSession();
                        }
                    },
                },
                config: {
                    responseModalities: [Modality.AUDIO], outputAudioTranscription: {}, inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
                    systemInstruction: systemInstruction,
                    tools: [{ functionDeclarations: [switchSkillFunctionDeclaration] }],
                },
            });
        } catch (error) {
            console.error("Error starting voice session:", error);
            setVoiceConnectionState('error');
            if (error instanceof DOMException && (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError')) {
                setApiError("I'll need microphone permission to hear you. Please try again and allow access when prompted in your browser settings.");
            } else if (error instanceof DOMException && error.name === 'NotFoundError') {
                setApiError("I couldn't find a microphone. Please make sure one is connected and enabled.");
            } else {
                setApiError("Could not start voice chat. Please check your network and try again.");
            }
            stopVoiceSession();
        }
    };

    const SkillButton: React.FC<{ skill: ActiveSkill, icon: React.ReactNode, label: string, description: string }> = ({ skill, icon, label, description }) => (
        <button onClick={() => { setActiveSkill(skill); setIsSkillModalOpen(false); if(skill !== 'voice' && voiceConnectionState !== 'idle') stopVoiceSession(); }}
            className={`flex flex-col items-center justify-center space-y-3 p-4 rounded-2xl transition-all aspect-square border ${activeSkill === skill ? 'bg-sky-50 dark:bg-sky-900/30 border-sky-200 dark:border-sky-800' : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 hover:shadow-lg hover:scale-[1.02]'}`}>
            <div className={`p-3 rounded-xl ${activeSkill === skill ? 'bg-sky-100 dark:bg-sky-900 text-sky-600 dark:text-sky-300' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300'}`}>
                {icon}
            </div>
            <div className="text-center">
                <span className={`block text-sm font-bold ${activeSkill === skill ? 'text-sky-700 dark:text-sky-200' : 'text-gray-800 dark:text-gray-200'}`}>{label}</span>
                <span className="text-xs text-gray-500 dark:text-gray-400 mt-1 line-clamp-2">{description}</span>
            </div>
        </button>
    );

    const SkillSelectionModal = () => (
         <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
             <div className="absolute inset-0 bg-black/40 backdrop-blur-md" onClick={() => setIsSkillModalOpen(false)} />
             <motion.div 
                initial={{ opacity: 0, scale: 0.9, y: 20 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.9, y: 20 }}
                className="relative bg-white dark:bg-gray-900 w-full max-w-2xl rounded-3xl shadow-2xl border border-gray-200 dark:border-gray-800 overflow-hidden max-h-[85vh] flex flex-col"
             >
                 <div className="p-6 border-b border-gray-100 dark:border-gray-800 flex justify-between items-center bg-gray-50/50 dark:bg-gray-800/50">
                     <div>
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <SparklesIcon className="h-5 w-5 text-purple-500" />
                            Select AI Capability
                        </h2>
                        <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">Choose a specialized agent for your task</p>
                     </div>
                     <button onClick={() => setIsSkillModalOpen(false)} className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 text-gray-500">
                         <XCircleIcon className="h-6 w-6" />
                     </button>
                 </div>

                 <div className="p-6 overflow-y-auto">
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                        <SkillButton skill="chat" icon={<ChatBubbleOvalLeftIcon className="h-8 w-8"/>} label="Chat" description="General conversational assistant" />
                        <SkillButton skill="imageGen" icon={<PhotoIcon className="h-8 w-8"/>} label="Image Gen" description="Create stunning visuals from text" />
                        <SkillButton skill="videoGen" icon={<VideoCameraIcon className="h-8 w-8"/>} label="Video Gen" description="Generate high-quality videos" />
                        <SkillButton skill="docGen" icon={<DocumentTextIcon className="h-8 w-8"/>} label="Doc Gen" description="Draft reports, plans & PDFs" />
                        <SkillButton skill="appGen" icon={<CodeBracketIcon className="h-8 w-8"/>} label="App Gen" description="Build full-stack applications" />
                        <SkillButton skill="voice" icon={<MicrophoneIcon className="h-8 w-8"/>} label="Voice Mode" description="Real-time voice conversation" />
                        <SkillButton skill="workflow" icon={<WorkflowIcon className="h-8 w-8"/>} label="Workflow" description="Optimize your daily tasks" />
                        <SkillButton skill="trends" icon={<TrendingUpIcon className="h-8 w-8"/>} label="Trends" description="Analyze market trends" />
                        <SkillButton skill="scamDetect" icon={<ShieldCheckIcon className="h-8 w-8"/>} label="Scam Detect" description="Identify potential fraud" />
                    </div>
                 </div>
             </motion.div>
         </div>
    );

    const VoiceControl = () => {
        let content;
        let buttonClass = "w-20 h-20 rounded-full flex items-center justify-center text-white shadow-lg transition-all duration-300";

        switch (voiceConnectionState) {
            case 'connecting':
                content = <LoadingSpinner />;
                buttonClass += " bg-gray-400 dark:bg-gray-700 cursor-not-allowed";
                break;
            case 'connected':
                content = <StopCircleIcon className="h-10 w-10" />;
                buttonClass += " bg-red-500 animate-pulse-shadow";
                break;
            case 'error':
            case 'idle':
            default:
                content = <MicrophoneIcon className="h-10 w-10" />;
                buttonClass += " bg-sky-500 hover:bg-sky-600";
                break;
        }

        const handleClick = () => {
            if (voiceConnectionState === 'idle' || voiceConnectionState === 'error') {
                startVoiceSession();
            } else if (voiceConnectionState === 'connected') {
                stopVoiceSession();
            }
        };

        return (
            <div className="flex flex-col items-center justify-center space-y-3 pt-2">
                <button onClick={handleClick} className={buttonClass} disabled={voiceConnectionState === 'connecting'} aria-label={voiceConnectionState === 'connected' ? 'Stop voice session' : 'Start voice session'}>
                    {content}
                </button>
                {voiceConnectionState === 'error' && <p className="text-xs text-red-500 mt-2">Connection error. Tap to retry.</p>}
            </div>
        );
    };

    return (
        <div className="h-full flex flex-col bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 relative">
            <header className="sticky top-0 bg-white/80 dark:bg-black/80 backdrop-blur-lg z-10 p-4 border-b border-gray-200 dark:border-gray-800 flex justify-between items-center">
                 <div className="flex items-center space-x-2">
                    <button onClick={onBack} aria-label="Back" className="p-2 -ml-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800"><ArrowLeftIcon className="h-5 w-5" /></button>
                </div>
                <div className="flex flex-col items-center text-center">
                    <h1 className="font-bold text-lg flex items-center space-x-2"><SparklesIcon className="h-5 w-5 text-purple-500"/><span>Nova</span></h1>
                     <p className="text-xs text-gray-500">Your AI Dost ❤️</p>
                </div>
                <div className="flex items-center space-x-3">
                    <div className="flex items-center p-1 rounded-full bg-gray-200 dark:bg-gray-800">
                        <button onClick={() => setActivePersona('creator')} className={`px-3 py-1.5 text-xs font-semibold rounded-full flex items-center space-x-1.5 transition-all ${activePersona === 'creator' ? 'bg-white dark:bg-black text-gray-800 dark:text-gray-100 shadow-sm' : 'text-gray-500'}`}>
                            <CreatorBrainIcon className="h-4 w-4" />
                            <span>Creator</span>
                        </button>
                        <button onClick={() => setActivePersona('brand')} className={`px-3 py-1.5 text-xs font-semibold rounded-full flex items-center space-x-1.5 transition-all ${activePersona === 'brand' ? 'bg-white dark:bg-black text-gray-800 dark:text-gray-100 shadow-sm' : 'text-gray-500'}`}>
                            <BrandBrainIcon className="h-4 w-4" />
                            <span>Brand</span>
                        </button>
                    </div>
                </div>
            </header>

            <main ref={messagesEndRef} className="flex-grow p-4 overflow-y-auto space-y-6 scrollbar-hide">
                {messages.map((msg) => (
                    <motion.div key={msg.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}
                        className={`flex items-start gap-3 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        {msg.role === 'model' && <div className="w-8 h-8 rounded-full bg-gradient-to-br from-purple-400 to-sky-500 flex-shrink-0 flex items-center justify-center"><SparklesIcon className="h-5 w-5 text-white"/></div>}
                        <div className={`p-3 rounded-2xl max-w-sm md:max-w-md relative ${msg.role === 'user' ? 'bg-sky-500 text-white rounded-br-none' : 'bg-white dark:bg-black border border-gray-200 dark:border-gray-800 rounded-bl-none'}`}>
                            {msg.uploadedImageUrl && <img src={msg.uploadedImageUrl} alt="user upload" className="rounded-lg mb-2 max-h-48" />}
                            {msg.imageUrl && <img src={msg.imageUrl} alt="generated content" className="rounded-lg mb-2" />}
                            {msg.videoUrl && (
                                <video controls src={msg.videoUrl} className="rounded-lg mb-2 w-full aspect-video bg-black" />
                            )}

                            {msg.role === 'model' ? (
                                <FormattedTextRenderer text={msg.text} />
                            ) : (
                                <p className="text-sm whitespace-pre-wrap">{msg.text}</p>
                            )}

                            {msg.imageUrl && <button onClick={() => handleDownloadImage(msg.id, msg.imageUrl!, `nova-image.jpg`)} className="absolute -bottom-3 -right-3 p-1.5 bg-gray-700 text-white rounded-full shadow-lg hover:bg-gray-900">{downloadingFile === msg.id ? <LoadingSpinner size="sm"/> : <DownloadIcon className="h-4 w-4" />}</button>}
                            {msg.pdfContent && <button onClick={() => handleDownloadPdf(msg.id, msg.pdfContent!, `nova-doc.pdf`)} className="absolute -bottom-3 -right-3 p-1.5 bg-gray-700 text-white rounded-full shadow-lg hover:bg-gray-900">{downloadingFile === msg.id ? <LoadingSpinner size="sm"/> : <DownloadIcon className="h-4 w-4" />}</button>}

                            {msg.role === 'model' && msg.fromSkill === 'appGen' && (
                                <div className="mt-3 flex items-center space-x-2">
                                     <button onClick={() => handleDownloadZip(msg.text)} className="flex items-center space-x-2 px-3 py-2 bg-gray-100 dark:bg-gray-800 rounded-lg text-sm font-semibold hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">
                                        <CodeBracketIcon className="h-4 w-4" />
                                        <span>Download Project (ZIP)</span>
                                     </button>
                                </div>
                            )}
                        </div>
                        {msg.role === 'user' && <img src={userProfile?.avatar} alt="user avatar" className="w-8 h-8 rounded-full flex-shrink-0"/>}
                    </motion.div>
                ))}
                 {loading && <div className="flex items-start gap-3 justify-start"><div className="w-8 h-8 rounded-full bg-gradient-to-br from-purple-400 to-sky-500 flex-shrink-0 flex items-center justify-center"><SparklesIcon className="h-5 w-5 text-white"/></div><div className="p-3 rounded-2xl max-w-sm bg-white dark:bg-black border border-gray-200 dark:border-gray-800 rounded-bl-none"><div className="flex items-center space-x-2"><LoadingSpinner /><p className="text-sm text-gray-600 dark:text-gray-400">{generationMessage || 'Thinking...'}</p></div></div></div>}
                 {activeSkill === 'voice' && voiceConnectionState !== 'idle' && <div className="p-4 bg-white/50 dark:bg-black/50 rounded-lg border border-gray-200 dark:border-gray-800">{liveTranscription.userInput && <div className="text-sm text-gray-500 dark:text-gray-400 text-right italic p-2">{liveTranscription.userInput}</div>}{liveTranscription.modelOutput && <div className="text-sm text-sky-700 dark:text-sky-300 p-2">{liveTranscription.modelOutput}</div>}{voiceConnectionState === 'connecting' && <div className="flex items-center space-x-2 text-gray-500"><LoadingSpinner size="sm" /><p>Connecting...</p></div>}</div>}
            </main>

            <footer className="p-2 sm:p-4 bg-white dark:bg-black border-t border-gray-200 dark:border-gray-800">
                {apiError && <p className="text-center text-xs text-red-400 mb-2 px-2">{apiError}</p>}
                {uploadedFile && <div className="px-2 pb-2"><div className="flex items-center justify-between p-2 rounded-lg bg-gray-100 dark:bg-gray-800 text-sm"><span className="truncate">{uploadedFile.name}</span><button onClick={() => setUploadedFile(null)} className="p-1 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700"><XCircleIcon className="h-5 w-5 text-gray-500"/></button></div></div>}
                 {activeSkill === 'voice' ? (
                    <VoiceControl />
                 ) : (
                    <form onSubmit={handleSendMessage} className="flex items-center space-x-2">
                        <button type="button" onClick={() => setIsSkillModalOpen(true)} aria-label="Select Skill" className="p-3 bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">
                             {activeSkill === 'chat' ? <SparklesIcon className="h-5 w-5 text-purple-500"/> : 
                              activeSkill === 'imageGen' ? <PhotoIcon className="h-5 w-5 text-sky-500"/> :
                              activeSkill === 'videoGen' ? <VideoCameraIcon className="h-5 w-5 text-pink-500"/> :
                              <SparklesIcon className="h-5 w-5 text-purple-500"/>}
                        </button>
                        <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*,text/plain,text/markdown" />
                        <button type="button" onClick={() => fileInputRef.current?.click()} aria-label="Attach file" className="p-3 bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700"><PaperClipIcon className="h-5 w-5"/></button>
                        <input type="text" value={input} onChange={(e) => setInput(e.target.value)} placeholder={`Message Nova (${activeSkill === 'chat' ? 'Chat' : activeSkill})...`} className="flex-grow p-3 border rounded-full bg-gray-100 dark:bg-gray-800 border-transparent focus:outline-none focus:ring-2 focus:ring-sky-500 text-gray-900 dark:text-gray-100" />
                        <button type="submit" disabled={(!input.trim() && !uploadedFile) || loading} aria-label="Send message" className="p-3 bg-sky-500 text-white rounded-full disabled:opacity-50 transition-all hover:bg-sky-600 focus:outline-none">
                            <PaperAirplaneIcon className="h-6 w-6" />
                        </button>
                    </form>
                 )}
                <AnimatePresence>
                    {isSkillModalOpen && <SkillSelectionModal />}
                </AnimatePresence>
            </footer>
        </div>
    );
};

export default NovaScreen;
]]></content>
</change>
